namespace sv_b9f329163eaf46c1a65e27a688524a23.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit (user session).
/// Each SignalR circuit gets its own instance, so different managers see independent state.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    public static readonly IReadOnlyList<Warehouse> AvailableWarehouses =
    [
        new("WH-001", "Warehouse A – East"),
        new("WH-002", "Warehouse B – West"),
        new("WH-003", "Warehouse C – Central"),
    ];

    private string _selectedWarehouseId = AvailableWarehouses[0].Id;

    public string SelectedWarehouseId => _selectedWarehouseId;

    /// <summary>Raised whenever the selected warehouse changes.</summary>
    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId)
            return;

        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        // Clear delegates to prevent leaks if callers forget to unsubscribe.
        OnChange = null;
    }
}

public sealed record Warehouse(string Id, string Name);

namespace sv_b9f329163eaf46c1a65e27a688524a23.Services;

/// <summary>
/// Simulates a database query for low-stock item counts.
/// Registered as a singleton — stateless, so safe to share across circuits.
/// </summary>
public sealed class InventoryAlertService
{
    /// <summary>
    /// Returns a simulated low-stock count for the given warehouse.
    /// In production this would query a database.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }
}

namespace sv_b9f329163eaf46c1a65e27a688524a23.Services;

/// <summary>
/// Scoped service that coordinates alert data between unrelated components within a single circuit.
/// One component polls and pushes data here; all subscribers are notified.
/// </summary>
public sealed class AlertNotificationService : IDisposable
{
    private int _lowStockCount;

    public int LowStockCount => _lowStockCount;

    /// <summary>Raised when any component publishes a new alert count.</summary>
    public event Action? OnAlertUpdated;

    /// <summary>
    /// Publish a new low-stock count. All subscribed components will be notified.
    /// </summary>
    public void PublishLowStockCount(int count)
    {
        _lowStockCount = count;
        OnAlertUpdated?.Invoke();
    }

    public void Dispose()
    {
        OnAlertUpdated = null;
    }
}

