@page "/dashboard"
@using sv_b9f329163eaf46c1a65e27a688524a23.Services
@using sv_b9f329163eaf46c1a65e27a688524a23.Components.Shared
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService InventoryAlerts
@inject AlertNotificationService AlertNotification
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-header d-flex align-items-center">
                <strong>Inventory Alerts</strong>
                <span class="ms-2">
                    <AlertBadge />
                </span>
            </div>
            <div class="card-body">
                <p>
                    Monitoring <strong>@CurrentWarehouseName</strong> for low-stock items.
                </p>
                <p>
                    <span class="text-muted">Low-stock items:</span>
                    <span class="fs-3 fw-bold text-danger">@AlertNotification.LowStockCount</span>
                </p>
                <p class="text-muted" style="font-size: 0.85rem;">
                    Polling every 10 seconds. Last check: @_lastCheck?.ToString("HH:mm:ss")
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card">
            <div class="card-header">
                <strong>Warehouse Info</strong>
            </div>
            <div class="card-body">
                <p><strong>Selected:</strong> @CurrentWarehouseName</p>
                <p><strong>ID:</strong> @WarehouseState.SelectedWarehouseId</p>
                <p class="text-muted">
                    Switch warehouses using the dropdown in the sidebar to see alerts update.
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private Timer? _pollingTimer;
    private DateTime? _lastCheck;

    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.SelectedWarehouseId)?.Name
        ?? "Unknown";

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertNotification.OnAlertUpdated += OnAlertUpdated;
        StartPolling();
    }

    private void StartPolling()
    {
        _pollingTimer?.Dispose();
        // Fire immediately, then every 10 seconds.
        _pollingTimer = new Timer(async _ => await PollAlerts(), null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    private async Task PollAlerts()
    {
        try
        {
            var count = await InventoryAlerts.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
            _lastCheck = DateTime.Now;
            // Publish to all subscribers (sidebar badge, this page, etc.)
            AlertNotification.PublishLowStockCount(count);
        }
        catch (ObjectDisposedException)
        {
            // Circuit was torn down; ignore.
        }
    }

    private void OnWarehouseChanged()
    {
        // Restart polling immediately for the new warehouse.
        StartPolling();
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertUpdated()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _pollingTimer?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertNotification.OnAlertUpdated -= OnAlertUpdated;
    }
}

